-- [6]
-- EIN profile across all 9 EIN tables in my rows: rows, non-blank, widths, zero placeholder, distinct normalized
WITH src AS (
  SELECT 'IRS527' t, EIN::string e FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS
  UNION ALL SELECT 'HOP', EIN::string FROM LIBRARY_MARTS.HEALTH.HEALTH__HOSPITAL_OFFICER_PAY
  UNION ALL SELECT 'F5500_EIN', EIN::string FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_DOL_FORM5500
  UNION ALL SELECT 'F5500_SPONS', SPONS_DFE_EIN::string FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_DOL_FORM5500
  UNION ALL SELECT 'A300_2023', EIN::string FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_300A_SUMMARY_2023
  UNION ALL SELECT 'A300_2024', EIN::string FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_300A_SUMMARY_2024
  UNION ALL SELECT 'A300_2025', EIN::string FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_300A_SUMMARY_2025
  UNION ALL SELECT 'CD_2023', EIN::string FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2023
  UNION ALL SELECT 'CD_2024', EIN::string FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2024
  UNION ALL SELECT 'CD_2025', EIN::string FROM LIBRARY_MARTS.LABOR.LABOR__FED_OSHA_ITA_CASE_DETAIL_2025
), n AS (SELECT t, e, REGEXP_REPLACE(e,'[^0-9]','') d FROM src)
SELECT t, COUNT(*) n_rows, COUNT_IF(NULLIF(TRIM(e),'') IS NOT NULL) nonblank,
  COUNT_IF(LENGTH(d)=9) w9, COUNT_IF(LENGTH(d)=8) w8, COUNT_IF(LENGTH(d) BETWEEN 1 AND 7) w_short, COUNT_IF(LENGTH(d)>9) w_long,
  COUNT_IF(LENGTH(d)>0 AND LPAD(d,9,'0')='000000000') zeros,
  COUNT(DISTINCT IFF(LENGTH(d) BETWEEN 7 AND 9 AND LPAD(d,9,'0')<>'000000000', LPAD(d,9,'0'), NULL)) distinct_ein
FROM n GROUP BY t ORDER BY t;

