per AS (SELECT u, ANY_VALUE(rn) rn, COUNT(*) n, SUM(amt) amt, SUM(IFF(inwin>0,amt,0)) amt_in, COUNT_IF(inwin>0) n_in, MIN(d) first_d, MAX(d) last_d FROM tf GROUP BY 1),
j AS (SELECT per.*, xu.nm, xu.ags, xu.act, xu.prov, JAROWINKLER_SIMILARITY(REGEXP_REPLACE(xu.nm,'[^A-Z0-9 ]',''),REGEXP_REPLACE(per.rn,'[^A-Z0-9 ]','')) jw FROM per JOIN xu ON per.u=xu.uei)
SELECT 'SUMMARY' u, NULL nm, NULL rn, NULL ags, COUNT(*)::string n_uei, SUM(n)::string rows_, ROUND(SUM(amt))::string dollars, COUNT_IF(n_in>0)::string uei_paid_in_window, ROUND(SUM(amt_in))::string dollars_in_window, COUNT_IF(jw>=85)::string name_agree, COUNT_IF(prov=1)::string prov_uei, COUNT_IF(prov=1 AND n_in>0)::string prov_uei_in_win, ROUND(SUM(IFF(prov=1,amt_in,0)))::string prov_dollars_in_win, (SELECT COUNT(DISTINCT TRIM(RECIPIENT_PARENT_UEI)) FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL_R2 WHERE TRIM(RECIPIENT_PARENT_UEI) IN (SELECT uei FROM xu))::string parent_uei_hits, MIN(first_d)::string first_d, MAX(last_d)::string last_d
