SELECT * FROM (SELECT u, nm, rn, ags, act::string, n::string, ROUND(amt)::string, n_in::string, ROUND(amt_in)::string, ROUND(pos_in)::string, jw::string, prov::string, NULL, NULL, NULL, first_d::string, last_d::string FROM j ORDER BY pos_in DESC NULLS LAST LIMIT 15);

-- [34]
-- UEI: LIBRARY_MARTS.SCIENCE_RESEARCH.SCIENCE_RESEARCH__FED_SBIR_STTR_AWARDS vs EXCL UEIs: matched UEIs, name agreement (JW>=85), dollars inside an exclusion window; summary row then top 15 by in-window dollars
WITH pv AS (SELECT DISTINCT SAM_NUMBER FROM LIBRARY_MARTS.HEALTH.HEALTH__SAM_EXCLUDED_PROVIDERS),
x AS (SELECT TRIM(UEI) uei, IFF(SAM_NUMBER IN (SELECT SAM_NUMBER FROM pv),1,0) prov, ACTIVATION_DATE::date act, COALESCE(TERMINATION_DATE,'2999-12-31'::date) term, UPPER(COALESCE(ENTITY_NAME, FIRST_NAME||' '||LAST_NAME)) nm, EXCLUDING_AGENCY ag FROM LIBRARY_MARTS.PROCUREMENT.PROCUREMENT__FED_SAM_EXCLUSIONS WHERE LENGTH(TRIM(UEI))=12),
xu AS (SELECT uei, MIN(act) act, MODE(nm) nm, LISTAGG(DISTINCT ag, ',') ags, MAX(prov) prov FROM x GROUP BY 1),
t AS (SELECT AWARD_RECORD_ID k, TRY_TO_DATE(COALESCE(TRY_TO_DATE(PROPOSAL_AWARD_DATE::string), TRY_TO_DATE(AWARD_YEAR::string||'-01-01'))::string) d, TRY_TO_NUMBER(AWARD_AMOUNT::string,38,2) amt, TRIM(UEI) u, UPPER(COMPANY) rn, SEQ8() rid FROM LIBRARY_MARTS.SCIENCE_RESEARCH.SCIENCE_RESEARCH__FED_SBIR_STTR_AWARDS WHERE TRIM(UEI) IN (SELECT uei FROM xu)),
tf AS (SELECT t.rid, ANY_VALUE(t.u) u, ANY_VALUE(t.rn) rn, ANY_VALUE(t.d) d, ANY_VALUE(t.amt) amt, COUNT(x.uei) inwin FROM t LEFT JOIN x ON x.uei=t.u AND t.d BETWEEN x.act AND x.term GROUP BY 1),
per AS (SELECT u, ANY_VALUE(rn) rn, COUNT(*) n, SUM(amt) amt, SUM(IFF(inwin>0,amt,0)) amt_in, SUM(IFF(inwin>0 AND amt>0,amt,0)) pos_in, COUNT_IF(inwin>0) n_in, MIN(d) first_d, MAX(d) last_d FROM tf GROUP BY 1),
j AS (SELECT per.*, xu.nm, xu.ags, xu.act, xu.prov, JAROWINKLER_SIMILARITY(REGEXP_REPLACE(xu.nm,'[^A-Z0-9 ]',''),REGEXP_REPLACE(per.rn,'[^A-Z0-9 ]','')) jw FROM per JOIN xu ON per.u=xu.uei)
SELECT 'SUMMARY' u, NULL nm, NULL rn, NULL ags, COUNT(*)::string n_uei, SUM(n)::string rows_, ROUND(SUM(amt))::string dollars, COUNT_IF(n_in>0)::string uei_paid_in_window, ROUND(SUM(amt_in))::string net_in_window, ROUND(SUM(pos_in))::string gross_pos_in_window, COUNT_IF(jw>=85)::string name_agree, COUNT_IF(prov=1)::string prov_uei, COUNT_IF(prov=1 AND n_in>0)::string prov_uei_in_win, ROUND(SUM(IFF(prov=1,amt_in,0)))::string prov_dollars_in_win, NULL::string parent_uei_hits, MIN(first_d)::string first_d, MAX(last_d)::string last_d
FROM j
UNION ALL
SELECT * FROM (SELECT u, nm, rn, ags, act::string, n::string, ROUND(amt)::string, n_in::string, ROUND(amt_in)::string, ROUND(pos_in)::string, jw::string, prov::string, NULL, NULL, NULL, first_d::string, last_d::string FROM j ORDER BY pos_in DESC NULLS LAST LIMIT 15);

-- [35]
-- USAF same-day exclusions 2026-07-17: every SAM record that day by USAF (companies and people), to see if the SBIR firms are one cluster
SELECT ACTIVATION_DATE::string act, EXCLUDING_AGENCY, EXCLUSION_TYPE, EXCLUSION_PROGRAM, IS_ENTITY_NOT_INDIVIDUAL::string ent, COALESCE(ENTITY_NAME, FIRST_NAME||' '||LAST_NAME) nm, UEI, CITY, STATE, TERMINATION_DATE_RAW FROM LIBRARY_MARTS.PROCUREMENT.PROCUREMENT__FED_SAM_EXCLUSIONS WHERE EXCLUDING_AGENCY='USAF' AND ACTIVATION_DATE::date BETWEEN '2026-05-01' AND '2026-08-11' ORDER BY 1, 6;

-- [36]
-- SBIR awards to the USAF-excluded firms: address, PI, contact, agency, phase, amount
SELECT UEI, COMPANY, ADDRESS1, CITY, STATE, PI_NAME, CONTACT_NAME, CONTACT_EMAIL, AGENCY, BRANCH, PHASE, AWARD_YEAR, AWARD_AMOUNT FROM LIBRARY_MARTS.SCIENCE_RESEARCH.SCIENCE_RESEARCH__FED_SBIR_STTR_AWARDS WHERE TRIM(UEI) IN ('VT3VHC7U8ZT5','RB4XFCMC9KZ7','EUNHL9KYVJS7','WWGQNYQZ2C73','CDXXNKM674G5','XCA4MTEGBML5') ORDER BY CITY, UEI, AWARD_YEAR;

-- [37]
-- SBIR: every award at 549 Cedar St, Newington CT, any UEI: firms, awards, dollars, agencies, years
SELECT COALESCE(TRIM(UEI),'(none)') uei, MODE(UPPER(COMPANY)) company, COUNT(*) awards, ROUND(SUM(TRY_TO_NUMBER(AWARD_AMOUNT::string,38,2))) dollars, LISTAGG(DISTINCT AGENCY, '; ') agencies, MIN(AWARD_YEAR)::string first_yr, MAX(AWARD_YEAR)::string last_yr
FROM LIBRARY_MARTS.SCIENCE_RESEARCH.SCIENCE_RESEARCH__FED_SBIR_STTR_AWARDS
WHERE UPPER(CITY) LIKE 'NEWINGTON%' AND UPPER(ADDRESS1) LIKE '549 CEDAR%' GROUP BY 1 ORDER BY 4 DESC;

-- [38]
-- Contracts R2: obligations to the 11 Newington UEIs excluded 2026-07-17, before and after the exclusion date
SELECT TRIM(RECIPIENT_UEI) uei, MODE(RECIPIENT_NAME) nm, COUNT(*) actions, ROUND(SUM(FEDERAL_ACTION_OBLIGATION)) dollars, ROUND(SUM(IFF(ACTION_DATE::date>='2026-07-17',FEDERAL_ACTION_OBLIGATION,0))) after_excl, COUNT_IF(ACTION_DATE::date>='2026-07-17') actions_after, MIN(ACTION_DATE)::string first_d, MAX(ACTION_DATE)::string last_d, LISTAGG(DISTINCT AWARDING_AGENCY_NAME, '; ') agencies
FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL_R2
WHERE TRIM(RECIPIENT_UEI) IN ('CDXXNKM674G5','CRJND3N4PUF9','D1SXL4D3SP49','D1Y4XGUJ7RM7','CZZXT6YD6375','CZV2WV13KNW5','VT3VHC7U8ZT5','NUFBQWHHQ3F9','NJY1HNAMS888','EUNHL9KYVJS7','RB4XFCMC9KZ7','WWGQNYQZ2C73') OR (UPPER(RECIPIENT_CITY_NAME)='NEWINGTON' AND RECIPIENT_STATE_CODE='CT' AND UPPER(RECIPIENT_NAME) RLIKE '.*(BRYKA|BEACON IND|NEOSKYE|SKYSTOCKS|SYRNATEC|MYONIKS|FABULOUS).*')
GROUP BY 1 ORDER BY 4 DESC;

-- [39]
-- UEI: LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL_R2 vs EXCL UEIs: matched UEIs, name agreement (JW>=85), dollars inside an exclusion window; summary row then top 15 by in-window dollars
WITH pv AS (SELECT DISTINCT SAM_NUMBER FROM LIBRARY_MARTS.HEALTH.HEALTH__SAM_EXCLUDED_PROVIDERS),
x AS (SELECT TRIM(UEI) uei, IFF(SAM_NUMBER IN (SELECT SAM_NUMBER FROM pv),1,0) prov, ACTIVATION_DATE::date act, COALESCE(TERMINATION_DATE,'2999-12-31'::date) term, UPPER(COALESCE(ENTITY_NAME, FIRST_NAME||' '||LAST_NAME)) nm, EXCLUDING_AGENCY ag FROM LIBRARY_MARTS.PROCUREMENT.PROCUREMENT__FED_SAM_EXCLUSIONS WHERE LENGTH(TRIM(UEI))=12),
xu AS (SELECT uei, MIN(act) act, MODE(nm) nm, LISTAGG(DISTINCT ag, ',') ags, MAX(prov) prov FROM x GROUP BY 1),
t AS (SELECT CONTRACT_AWARD_UNIQUE_KEY k, TRY_TO_DATE(ACTION_DATE::string) d, TRY_TO_NUMBER(FEDERAL_ACTION_OBLIGATION::string,38,2) amt, TRIM(RECIPIENT_UEI) u, UPPER(RECIPIENT_NAME) rn, SEQ8() rid FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL_R2 WHERE TRIM(RECIPIENT_UEI) IN (SELECT uei FROM xu)),
tf AS (SELECT t.rid, ANY_VALUE(t.u) u, ANY_VALUE(t.rn) rn, ANY_VALUE(t.d) d, ANY_VALUE(t.amt) amt, COUNT(x.uei) inwin FROM t LEFT JOIN x ON x.uei=t.u AND t.d BETWEEN x.act AND x.term GROUP BY 1),
per AS (SELECT u, ANY_VALUE(rn) rn, COUNT(*) n, SUM(amt) amt, SUM(IFF(inwin>0,amt,0)) amt_in, SUM(IFF(inwin>0 AND amt>0,amt,0)) pos_in, COUNT_IF(inwin>0) n_in, MIN(d) first_d, MAX(d) last_d FROM tf GROUP BY 1),
j AS (SELECT per.*, xu.nm, xu.ags, xu.act, xu.prov, JAROWINKLER_SIMILARITY(REGEXP_REPLACE(xu.nm,'[^A-Z0-9 ]',''),REGEXP_REPLACE(per.rn,'[^A-Z0-9 ]','')) jw FROM per JOIN xu ON per.u=xu.uei)
SELECT 'SUMMARY' u, NULL nm, NULL rn, NULL ags, COUNT(*)::string n_uei, SUM(n)::string rows_, ROUND(SUM(amt))::string dollars, COUNT_IF(n_in>0)::string uei_paid_in_window, ROUND(SUM(amt_in))::string net_in_window, ROUND(SUM(pos_in))::string gross_pos_in_window, COUNT_IF(jw>=85)::string name_agree, COUNT_IF(prov=1)::string prov_uei, COUNT_IF(prov=1 AND n_in>0)::string prov_uei_in_win, ROUND(SUM(IFF(prov=1,amt_in,0)))::string prov_dollars_in_win, (SELECT COUNT(DISTINCT TRIM(RECIPIENT_PARENT_UEI)) FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL_R2 WHERE TRIM(RECIPIENT_PARENT_UEI) IN (SELECT uei FROM xu))::string parent_uei_hits, MIN(first_d)::string first_d, MAX(last_d)::string last_d
FROM j
UNION ALL
SELECT * FROM (SELECT u, nm, rn, ags, act::string, n::string, ROUND(amt)::string, n_in::string, ROUND(amt_in)::string, ROUND(pos_in)::string, jw::string, prov::string, NULL, NULL, NULL, first_d::string, last_d::string FROM j ORDER BY pos_in DESC NULLS LAST LIMIT 15);

-- [40]
-- ATI Government Solutions (SBA exclusion 2025-10-21): actions by table and fiscal half, FULL vs R2
SELECT 'FULL' src, TRIM(RECIPIENT_UEI) u, IFF(ACTION_DATE::date>='2025-10-21','after','before') w, COUNT(*) n, ROUND(SUM(FEDERAL_ACTION_OBLIGATION)) amt, MIN(ACTION_DATE)::string mn, MAX(ACTION_DATE)::string mx, LISTAGG(DISTINCT AWARDING_AGENCY_NAME,'; ') ag FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL WHERE TRIM(RECIPIENT_UEI)='C1ZLDAS18FJ3' GROUP BY 1,2,3
UNION ALL SELECT 'R2', TRIM(RECIPIENT_UEI), IFF(ACTION_DATE::date>='2025-10-21','after','before'), COUNT(*), ROUND(SUM(FEDERAL_ACTION_OBLIGATION)), MIN(ACTION_DATE)::string, MAX(ACTION_DATE)::string, LISTAGG(DISTINCT AWARDING_AGENCY_NAME,'; ') FROM LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_USASPENDING_CONTRACTS_FULL_R2 WHERE TRIM(RECIPIENT_UEI)='C1ZLDAS18FJ3' OR UPPER(RECIPIENT_NAME) LIKE 'ATI GOVERNMENT SOLUTIONS%' GROUP BY 1,2,3
UNION ALL SELECT 'SAM', UEI, EXCLUSION_TYPE||' / '||COALESCE(EXCLUSION_PROGRAM,''), NULL, NULL, ACTIVATION_DATE::string, TERMINATION_DATE_RAW, EXCLUDING_AGENCY FROM LIBRARY_MARTS.PROCUREMENT.PROCUREMENT__FED_SAM_EXCLUSIONS WHERE UEI='C1ZLDAS18FJ3';
